app_css:
.tool-app-altertrack { color: #3b0764; max-width: 1100px; margin-inline: auto; }
.tool-app-altertrack .atr-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; margin: 12px 0; }
.tool-app-altertrack .atr-stat { background: #faf5ff; border: 1px solid #e9d5ff; border-radius: 12px; padding: 10px 14px; text-align: center; }
.tool-app-altertrack .atr-stat-num { display: block; font-size: 24px; font-weight: 800; color: #A21CAF; }
.tool-app-altertrack .atr-stat-warn .atr-stat-num { color: #b45309; }
.tool-app-altertrack .atr-stat-bad .atr-stat-num { color: #b91c1c; }
.tool-app-altertrack .atr-stat-label { font-size: 12px; font-weight: 600; color: #6b21a8; }
.tool-app-altertrack .atr-toolbar { display: flex; gap: 10px; flex-wrap: wrap; margin: 12px 0; align-items: center; }
.tool-app-altertrack #atr-search { flex: 1 1 220px; border: 1px solid #d8b4fe; border-radius: 10px; padding: 10px 12px; font-size: 14px; }
.tool-app-altertrack #atr-filter { border: 1px solid #d8b4fe; border-radius: 10px; padding: 10px 12px; font-size: 14px; background: #fff; }
.tool-app-altertrack .atr-btn { background: #A21CAF; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-altertrack .atr-btn:hover { background: #86198f; }
.tool-app-altertrack .atr-btn-ghost { background: #f5f3ff; color: #A21CAF; }
.tool-app-altertrack .atr-btn-ghost:hover { background: #ede9fe; }
.tool-app-altertrack .atr-form { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; background: #faf5ff; border: 1px solid #e9d5ff; border-radius: 14px; padding: 16px; margin: 12px 0; }
.tool-app-altertrack .atr-form[hidden] { display: none; }
.tool-app-altertrack .atr-span2 { grid-column: 1 / -1; }
.tool-app-altertrack .atr-form label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-altertrack .atr-form input, .tool-app-altertrack .atr-form textarea { border: 1px solid #d8b4fe; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; font-family: inherit; }
.tool-app-altertrack .atr-form-actions { display: flex; gap: 10px; }
.tool-app-altertrack .atr-board { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 12px; margin: 12px 0; align-items: start; }
.tool-app-altertrack .atr-col { background: #faf5ff; border: 1px solid #e9d5ff; border-radius: 14px; padding: 10px; min-height: 120px; }
.tool-app-altertrack .atr-col h3 { margin: 4px 6px 10px; font-size: 13px; text-transform: uppercase; letter-spacing: 0.04em; color: #6b21a8; display: flex; justify-content: space-between; }
.tool-app-altertrack .atr-col h3 .atr-count { background: #e9d5ff; border-radius: 999px; padding: 0 8px; font-size: 12px; }
.tool-app-altertrack .atr-empty { color: #a855f7; font-size: 13px; text-align: center; padding: 14px 6px; }
.tool-app-altertrack .atr-card { background: #fff; border: 1px solid #e9d5ff; border-left: 5px solid #A21CAF; border-radius: 10px; padding: 10px 12px; margin-bottom: 10px; font-size: 13px; }
.tool-app-altertrack .atr-card-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
.tool-app-altertrack .atr-num { font-weight: 800; color: #A21CAF; }
.tool-app-altertrack .atr-due { font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 999px; background: #f5f3ff; color: #6b21a8; }
.tool-app-altertrack .atr-due-warn { background: #fef3c7; color: #92400e; }
.tool-app-altertrack .atr-due-bad { background: #fee2e2; color: #b91c1c; }
.tool-app-altertrack .atr-cust { font-weight: 700; font-size: 15px; }
.tool-app-altertrack .atr-meta { color: #6b21a8; margin: 2px 0; }
.tool-app-altertrack .atr-detail { white-space: pre-wrap; margin: 4px 0; }
.tool-app-altertrack .atr-balance { font-weight: 700; margin: 4px 0; }
.tool-app-altertrack .atr-balance.atr-paid { color: #15803d; font-weight: 600; }
.tool-app-altertrack .atr-card-actions { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
.tool-app-altertrack .atr-card-actions button { border: 1px solid #d8b4fe; background: #faf5ff; color: #6b21a8; border-radius: 8px; padding: 5px 10px; font-size: 12px; font-weight: 700; cursor: pointer; }
.tool-app-altertrack .atr-card-actions button:hover { background: #f3e8ff; }
.tool-app-altertrack .atr-card-actions button.atr-danger { color: #b91c1c; border-color: #fecaca; background: #fff; }
.tool-app-altertrack .tool-print-doc { display: none; }
@media print {
  .tool-app-altertrack .atr-stats, .tool-app-altertrack .atr-toolbar,
  .tool-app-altertrack .atr-form, .tool-app-altertrack .atr-board { display: none !important; }
  .tool-app-altertrack .tool-print-doc { display: block !important; color: #000; }
  .tool-app-altertrack .tool-print-doc .atr-ticket { border: 2px dashed #000; border-radius: 8px; padding: 18px; max-width: 420px; }
  .tool-app-altertrack .tool-print-doc h2 { margin: 0 0 8px; }
  .tool-app-altertrack .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 10px 0; }
  .tool-app-altertrack .tool-print-doc td { padding: 4px 6px; font-size: 14px; vertical-align: top; }
  .tool-app-altertrack .tool-print-doc td:first-child { font-weight: 700; white-space: nowrap; width: 110px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  var LS_KEY = 'toolapp-altertrack-tickets';
  var SEQ_KEY = 'toolapp-altertrack-seq';
  var STATUS = [
    { key: 'received', label: 'Received' },
    { key: 'progress', label: 'In Progress' },
    { key: 'ready', label: 'Ready' },
    { key: 'picked', label: 'Picked Up' }
  ];
  function todayStr() {
    var d = new Date();
    return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2);
  }
  function fmtDate(iso) {
    if (!iso) return '';
    var p = iso.split('-');
    if (p.length !== 3) return iso;
    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return months[parseInt(p[1], 10) - 1] + ' ' + parseInt(p[2], 10);
  }
  function getTickets() {
    try { return JSON.parse(localStorage.getItem(LS_KEY)) || []; } catch (e) { return []; }
  }
  function setTickets(t) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(t)); } catch (e) {}
  }
  function nextNum() {
    var n = 0;
    try { n = parseInt(localStorage.getItem(SEQ_KEY) || '0', 10) || 0; } catch (e) {}
    n += 1;
    try { localStorage.setItem(SEQ_KEY, String(n)); } catch (e) {}
    return 'AT-' + ('0000' + n).slice(-4);
  }
  function statusLabel(k) {
    for (var i = 0; i < STATUS.length; i++) if (STATUS[i].key === k) return STATUS[i].label;
    return k;
  }
  function nextStatus(k) {
    for (var i = 0; i < STATUS.length - 1; i++) if (STATUS[i].key === k) return STATUS[i + 1].key;
    return null;
  }
  function prevStatus(k) {
    for (var i = 1; i < STATUS.length; i++) if (STATUS[i].key === k) return STATUS[i - 1].key;
    return null;
  }
  function dueInfo(t) {
    if (t.status === 'picked' || !t.due) return null;
    var today = todayStr();
    if (t.due < today) return { cls: 'atr-due-bad', text: 'Overdue' };
    if (t.due === today) return { cls: 'atr-due-warn', text: 'Due today' };
    return { cls: '', text: 'Due ' + fmtDate(t.due) };
  }
  function matches(t, q, f) {
    if (f && t.status !== f) return false;
    if (!q) return true;
    var hay = (t.num + ' ' + t.name + ' ' + t.phone + ' ' + t.garment + ' ' + t.detail).toLowerCase();
    return hay.indexOf(q) !== -1;
  }
  function renderStats(tickets) {
    var rack = 0, due = 0, overdue = 0, owed = 0;
    var today = todayStr();
    for (var i = 0; i < tickets.length; i++) {
      var t = tickets[i];
      var open = t.status !== 'picked';
      if (open) {
        rack += 1;
        owed += (parseFloat(t.price) || 0) - (parseFloat(t.deposit) || 0);
        if (t.due === today) due += 1;
        else if (t.due && t.due < today) overdue += 1;
      }
    }
    $('atr-stat-rack').textContent = rack;
    $('atr-stat-due').textContent = due;
    $('atr-stat-overdue').textContent = overdue;
    $('atr-stat-owed').textContent = money(owed);
  }
  function cardHtml(t) {
    var d = dueInfo(t);
    var badge = d ? '<span class="atr-due ' + d.cls + '">' + esc(d.text) + '</span>' : '';
    var bal = (parseFloat(t.price) || 0) - (parseFloat(t.deposit) || 0);
    var balHtml = bal > 0
      ? '<div class="atr-balance">Balance due: ' + money(bal) + '</div>'
      : '<div class="atr-balance atr-paid">Paid in full</div>';
    var meta = esc(t.garment || '');
    if (t.phone) meta += (meta ? ' &middot; ' : '') + esc(t.phone);
    var fwd = nextStatus(t.status), back = prevStatus(t.status);
    var actions = '';
    if (back) actions += '<button type="button" data-act="back" data-id="' + t.id + '">\u2039 Back</button>';
    if (fwd) actions += '<button type="button" data-act="fwd" data-id="' + t.id + '">Move to ' + esc(statusLabel(fwd)) + ' \u203a</button>';
    actions += '<button type="button" data-act="print" data-id="' + t.id + '">Print</button>';
    actions += '<button type="button" data-act="edit" data-id="' + t.id + '">Edit</button>';
    actions += '<button type="button" class="atr-danger" data-act="del" data-id="' + t.id + '" aria-label="Delete ticket">\u00d7</button>';
    return '<article class="atr-card">' +
      '<div class="atr-card-top"><span class="atr-num">' + esc(t.num) + '</span>' + badge + '</div>' +
      '<div class="atr-cust">' + esc(t.name || 'No name') + '</div>' +
      (meta ? '<div class="atr-meta">' + meta + '</div>' : '') +
      (t.detail ? '<div class="atr-detail">' + esc(t.detail) + '</div>' : '') +
      balHtml +
      '<div class="atr-card-actions">' + actions + '</div>' +
      '</article>';
  }
  function render() {
    var tickets = getTickets();
    renderStats(tickets);
    var q = ($('atr-search').value || '').toLowerCase().trim();
    var f = $('atr-filter').value;
    var board = $('atr-board');
    board.innerHTML = '';
    for (var c = 0; c < STATUS.length; c++) {
      var col = document.createElement('section');
      col.className = 'atr-col';
      var list = [];
      for (var i = 0; i < tickets.length; i++) {
        if (tickets[i].status === STATUS[c].key && matches(tickets[i], q, f)) list.push(tickets[i]);
      }
      list.sort(function (a, b) {
        var da = a.due || '9999', db = b.due || '9999';
        return da < db ? -1 : da > db ? 1 : 0;
      });
      var html = '<h3>' + esc(STATUS[c].label) + '<span class="atr-count">' + list.length + '</span></h3>';
      if (!list.length) html += '<div class="atr-empty">No tickets</div>';
      for (var j = 0; j < list.length; j++) html += cardHtml(list[j]);
      col.innerHTML = html;
      board.appendChild(col);
    }
  }
  function findTicket(id) {
    var tickets = getTickets();
    for (var i = 0; i < tickets.length; i++) if (tickets[i].id === id) return { t: tickets[i], i: i, all: tickets };
    return null;
  }
  function openForm(t) {
    $('atr-f-id').value = t ? t.id : '';
    $('atr-f-name').value = t ? t.name : '';
    $('atr-f-phone').value = t ? t.phone : '';
    $('atr-f-garment').value = t ? t.garment : '';
    $('atr-f-due').value = t ? t.due : '';
    $('atr-f-detail').value = t ? t.detail : '';
    $('atr-f-measure').value = t ? t.measure : '';
    $('atr-f-price').value = t ? t.price : 0;
    $('atr-f-deposit').value = t ? t.deposit : 0;
    $('atr-form').hidden = false;
    $('atr-f-name').focus();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
  function closeForm() { $('atr-form').hidden = true; }
  function saveForm() {
    var id = $('atr-f-id').value;
    var name = $('atr-f-name').value.trim();
    if (!name) { $('atr-f-name').focus(); return; }
    var data = {
      name: name,
      phone: $('atr-f-phone').value.trim(),
      garment: $('atr-f-garment').value.trim(),
      due: $('atr-f-due').value,
      detail: $('atr-f-detail').value.trim(),
      measure: $('atr-f-measure').value.trim(),
      price: parseFloat($('atr-f-price').value) || 0,
      deposit: parseFloat($('atr-f-deposit').value) || 0
    };
    var tickets = getTickets();
    if (id) {
      for (var i = 0; i < tickets.length; i++) {
        if (tickets[i].id === id) {
          for (var k in data) tickets[i][k] = data[k];
          break;
        }
      }
    } else {
      data.id = 't' + Date.now().toString(36) + Math.floor(Math.random() * 1e4).toString(36);
      data.num = nextNum();
      data.status = 'received';
      data.createdAt = new Date().toISOString();
      tickets.unshift(data);
    }
    setTickets(tickets);
    closeForm();
    render();
  }
  function printTicket(id) {
    var found = findTicket(id);
    if (!found) return;
    var t = found.t;
    var bal = (parseFloat(t.price) || 0) - (parseFloat(t.deposit) || 0);
    var rows =
      '<tr><td>Ticket</td><td>' + esc(t.num) + '</td></tr>' +
      '<tr><td>Customer</td><td>' + esc(t.name) + (t.phone ? '<br>' + esc(t.phone) : '') + '</td></tr>' +
      '<tr><td>Garment</td><td>' + esc(t.garment || '-') + '</td></tr>' +
      '<tr><td>Alterations</td><td>' + esc(t.detail || '-').replace(/\n/g, '<br>') + '</td></tr>' +
      '<tr><td>Measurements</td><td>' + esc(t.measure || '-').replace(/\n/g, '<br>') + '</td></tr>' +
      '<tr><td>Due</td><td>' + esc(t.due ? fmtDate(t.due) : '-') + '</td></tr>' +
      '<tr><td>Price</td><td>' + money(t.price) + '</td></tr>' +
      '<tr><td>Deposit</td><td>' + money(t.deposit) + '</td></tr>' +
      '<tr><td>Balance due</td><td><strong>' + money(bal) + '</strong></td></tr>';
    $('atr-printdoc').innerHTML =
      '<div class="atr-ticket"><h2>Alteration Claim Ticket</h2>' +
      '<table>' + rows + '</table>' +
      '<p>Present this ticket at pickup. Thank you!</p></div>';
    window.print();
  }
  $('atr-new').addEventListener('click', function () { openForm(null); });
  $('atr-f-cancel').addEventListener('click', closeForm);
  $('atr-form').addEventListener('submit', function (e) { e.preventDefault(); saveForm(); });
  $('atr-search').addEventListener('input', render);
  $('atr-filter').addEventListener('change', render);
  $('atr-board').addEventListener('click', function (e) {
    var btn = e.target.closest ? e.target.closest('button[data-act]') : null;
    if (!btn) return;
    var act = btn.getAttribute('data-act');
    var id = btn.getAttribute('data-id');
    var found = findTicket(id);
    if (!found) return;
    if (act === 'fwd') {
      var ns = nextStatus(found.t.status);
      if (ns) { found.all[found.i].status = ns; setTickets(found.all); render(); }
    } else if (act === 'back') {
      var ps = prevStatus(found.t.status);
      if (ps) { found.all[found.i].status = ps; setTickets(found.all); render(); }
    } else if (act === 'del') {
      if (confirm('Delete ticket ' + found.t.num + '?')) {
        found.all.splice(found.i, 1);
        setTickets(found.all);
        render();
      }
    } else if (act === 'edit') {
      openForm(found.t);
    } else if (act === 'print') {
      printTicket(id);
    }
  });
  render();
})();
